#include <stdio.h>

int main() {
    int temps[] = {-8, -3, -15, -6};
    int n = 4;
    int max = temps[0];
    for (int i = 1; i < n; i++) {
        if (temps[i] > max) {
            max = temps[i];
        }
    }
    printf("Highest: %d\n", max);
    return 0;
}
